    const {method, headers, body} = requestData(init, paymentAuthorization, source);
    const controller = new AbortController();
    const {signal} = controller;
    const stop = () => controller.abort(init.signal.reason);
    if (init.signal?.aborted) controller.abort(init.signal.reason);
    else init.signal?.addEventListener('abort', stop, {once:true});
    // Deadline includes DNS, TLS, response and downstream body consumption.
    const timer = setTimeout(() => controller.abort(new PublicTransportError('PUBLIC_HTTPS_TIMEOUT')), timeoutMs);
    let incoming, stopTunnel;
    const cleanup = () => {
      clearTimeout(timer); init.signal?.removeEventListener('abort', stop); stopTunnel?.();
    };
    try {
      signal.throwIfAborted();
      let connection;
      if (profile !== null) {
        // The operator approves this exact origin and explicit resolving proxy.
        // Preserve the original merchant SNI/TLS and HTTP request inside it.
        const tunnel = oneShotConnectAgent({target:url, proxy, resolveAtProxy:true, signal});
        stopTunnel = tunnel.stop;
        connection = {agent:tunnel.agent};
      } else {
        const answers = await abortable(lookup(url.hostname, {all:true, verbatim:true}), signal);
        signal.throwIfAborted();
        if (!Array.isArray(answers) || !answers.length || answers.length > 64 || answers.some(
          row => !row || ![4,6].includes(row.family) || isIP(row.address) !== row.family))
          fail('NONPUBLIC_DNS_ANSWER');
        if (sandboxGatewayIPv4 === null) {
          if (answers.some(row => !isPublicAddress(row.address))) fail('NONPUBLIC_DNS_ANSWER');
        } else {
          // Fail closed on stale/mixed DNS, including one public plus one gateway.
          // Original hostname, port, SNI, TLS and pinned lookup remain unchanged.
          if (answers.length !== 1 || answers[0].family !== 4 ||
              answers[0].address !== sandboxGatewayIPv4)
            fail('SANDBOX_GATEWAY_DNS_MISMATCH');
        }
        // Copy validated primitives: the trusted resolver's mutable return object
        // cannot alter the address after policy validation.
        const {address, family} = answers[0];
        const pinnedLookup = (host, options, callback) => {
          if (typeof options === 'function') { callback = options; options = {}; }
          if (host !== url.hostname) { callback(new PublicTransportError('DNS_PIN_HOST_MISMATCH')); return; }
          if (options?.all) callback(null, [{address, family}]);
          else callback(null, address, family);
        };
        connection = {lookup:pinnedLookup, family, autoSelectFamily:false, agent:false};
      }
      incoming = await new Promise((resolve, reject) => {
        const req = requestImpl({
          protocol:'https:', hostname:url.hostname, port:443,
          // href preserves an explicit empty query, which URL.search drops.
          // SF31 binds this exact resource identity before approving payment.
          path:url.href.slice(url.origin.length), method, headers,
          ...connection, servername:url.hostname, rejectUnauthorized:true,
          checkServerIdentity, minVersion:'TLSv1.2', maxHeaderSize:65_536, signal
        }, resolve);
        req.once('error', reject);
        req.end(body);
      });
      signal.throwIfAborted();
      const responseHeaders = new Headers();
      for (let i=0; i<incoming.rawHeaders.length; i+=2)
        responseHeaders.append(incoming.rawHeaders[i], incoming.rawHeaders[i+1]);
      if (responseHeaders.has('content-encoding') && responseHeaders.get('content-encoding').toLowerCase() !== 'identity')
        fail('UNSUPPORTED_CONTENT_ENCODING');
      // No redirects, automatic auth, cookies, implicit proxy, pooled socket or
      // reconnect: at most one original request per invocation.
      incoming.once('close', cleanup);
      const noBody = method === 'HEAD' || [204,205,304].includes(incoming.statusCode);
      const stream = noBody ? null : Readable.toWeb(incoming, {
        strategy: {highWaterMark:65_536, size:chunk => chunk.byteLength}
      });
      if (noBody) incoming.resume();
      const response = new Response(stream, {status:incoming.statusCode, headers:responseHeaders});
      Object.defineProperty(response, 'url', {value:url.href});
      return response;
    } catch (error) {
      incoming?.destroy(); cleanup();
      throw error;
    }
  };
}

// MIT License. Save one already-returned buyer response; never send a request.
import { createHash, randomUUID } from 'node:crypto';
import { open, lstat, realpath, link, unlink } from 'node:fs/promises';
import { basename, dirname, isAbsolute, join, resolve } from 'node:path';
import { createResponseStreamParser, normalizeResponseStream, responseStreamContentType,
  BuyerResponseStreamError } from './response-stream.mjs';

export class BuyerResponseFileError extends Error {
  constructor(code, detail = '', { cause, bytes = 0, partialPath = null, cleanupWarnings = [] } = {}) {
    super(`${code}${detail ? ': ' + detail : ''}`, { cause });
    this.name = 'BuyerResponseFileError';
    this.code = code;
    this.bytes = bytes;
    this.partialPath = partialPath;
    this.cleanupWarnings = cleanupWarnings;
  }
}

/** Local expectations are supplied before purchase, never learned from the
 * response's digest header. This validates content consistency, not seller identity. */
export function validateResponseFileIntegrity({ expectedSha256, expectedBytes,
  expectedContentType } = {}, maxBytes = Number.MAX_SAFE_INTEGER) {
  const pins = {};
  if (expectedSha256 !== undefined) {
    if (typeof expectedSha256 !== 'string' || !/^[a-f0-9]{64}$/.test(expectedSha256))
      throw new BuyerResponseFileError('BAD_RESPONSE_FILE_EXPECTED_SHA256');
    pins.expectedSha256 = expectedSha256;
  }
  if (expectedBytes !== undefined) {
    if (!Number.isSafeInteger(expectedBytes) || expectedBytes < 0 || expectedBytes > maxBytes)
      throw new BuyerResponseFileError('BAD_RESPONSE_FILE_EXPECTED_BYTES');
    pins.expectedBytes = expectedBytes;
  }
  if (expectedContentType !== undefined) {
    if (typeof expectedContentType !== 'string' || expectedContentType.length > 127 ||
        !/^[A-Za-z0-9!#$&^_.+-]+\/[A-Za-z0-9!#$&^_.+-]+$/.test(expectedContentType))
      throw new BuyerResponseFileError('BAD_RESPONSE_FILE_EXPECTED_TYPE');
    pins.expectedContentType = expectedContentType.toLowerCase();
  }
  return Object.freeze(pins);
}

async function absent(path) {
  try { await lstat(path); }
  catch (error) { if (error.code === 'ENOENT') return; throw error; }
  throw new BuyerResponseFileError('RESPONSE_FILE_EXISTS', path);
}

function readChunk(reader, signal) {
  if (signal.aborted) return Promise.reject(signal.reason);
  return new Promise((resolve, reject) => {
    const finish = (settle, value) => {
      signal.removeEventListener('abort', onAbort);
      settle(value);
    };
    const onAbort = () => finish(reject, signal.reason);
    signal.addEventListener('abort', onAbort, { once: true });
    try { reader.read().then(value => finish(resolve, value), error => finish(reject, error)); }
    catch (error) { finish(reject, error); }
  });
}

/** Reserve a caller-chosen destination BEFORE calling the buyer. The parent
 * must be an existing, trusted directory on a hard-link-capable filesystem. */
export async function prepareBuyerResponseFile({ destination, maxBytes = 64 * 1024 * 1024,
  timeoutMs = 30_000, expectedSha256, expectedBytes, expectedContentType, stream, reservationTag } = {}) {
  if (typeof destination !== 'string' || !isAbsolute(destination) || destination.includes('\0') ||
      /[\\/]$/.test(destination) || ['.', '..'].includes(basename(destination)))
    throw new BuyerResponseFileError('BAD_RESPONSE_FILE_DESTINATION', 'absolute file path required');
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 1)
    throw new BuyerResponseFileError('BAD_RESPONSE_FILE_LIMIT');
  if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 2_147_483_647)
    throw new BuyerResponseFileError('BAD_RESPONSE_FILE_TIMEOUT');
  if (reservationTag !== undefined && (typeof reservationTag !== 'string' ||
      !/^[A-Za-z0-9._:-]{1,96}$/.test(reservationTag)))
    throw new BuyerResponseFileError('BAD_RESPONSE_FILE_RESERVATION_TAG');
  const pins = validateResponseFileIntegrity({ expectedSha256, expectedBytes, expectedContentType }, maxBytes);
  const streamOptions = stream === undefined ? null : normalizeResponseStream(stream);
  if (streamOptions && pins.expectedContentType &&
      !responseStreamContentType(streamOptions.format, pins.expectedContentType))
    throw new BuyerResponseFileError('BAD_RESPONSE_STREAM_EXPECTED_TYPE');

  let finalPath, reservationPath, partialPath, probePath, reservation, file;
  let state = 'PREPARING', activeSave = null, bytes = 0;
  const controller = new AbortController();

  async function cleanup({ keepPartial = false } = {}) {
    const warnings = [];
    for (const [handle, path] of [[file, partialPath], [reservation, reservationPath]]) {
      if (handle) {
        try { await handle.close(); }
        catch (error) { warnings.push({ path, code: error.code ?? 'CLOSE_FAILED' }); }
      }
    }
    file = null; reservation = null;
    for (const path of [probePath, !keepPartial && partialPath, reservationPath]) {
      if (!path) continue;
      try { await unlink(path); }
      catch (error) { if (error.code !== 'ENOENT') warnings.push({ path, code: error.code ?? 'UNLINK_FAILED' }); }
    }
    return warnings;
  }

  try {
    const parent = await realpath(dirname(resolve(destination)));
    finalPath = join(parent, basename(destination));
    await absent(finalPath);
    // A filename-derived reservation follows the parent filesystem's own
    // case comparison, unlike a hash which gives case aliases different locks.
    const lockPath = join(parent, `.${basename(finalPath)}.x402-download.lock`);
    try { reservation = await open(lockPath, 'wx', 0o600); }
    catch (cause) {
      throw new BuyerResponseFileError(cause.code === 'EEXIST' ? 'RESPONSE_FILE_RESERVED' : 'RESPONSE_FILE_PREPARE_FAILED', finalPath, { cause });
    }
    // Record only paths actually created by this instance: never unlink another
    // process's existing lock or a coincidentally named partial file.
    reservationPath = lockPath;
    const candidate = join(parent, `.x402-response-${randomUUID()}.partial`);
    file = await open(candidate, 'wx', 0o600);
    partialPath = candidate;
    await reservation.writeFile(JSON.stringify({ destination: finalPath, partialPath, pid: process.pid,
      ...(reservationTag === undefined ? {} : { reservationTag }) }) + '\n');
    await reservation.sync();
    // Discover unsupported hard links before the caller sends a paid request.
    const probe = join(parent, `.x402-link-${randomUUID()}`);
    await link(partialPath, probe);
    probePath = probe;
    await unlink(probePath);
    probePath = null;
    await absent(finalPath);
    state = 'PREPARED';
  } catch (cause) {
    const cleanupWarnings = await cleanup();
    const error = cause instanceof BuyerResponseFileError ? cause : new BuyerResponseFileError('RESPONSE_FILE_PREPARE_FAILED', '', { cause });
    error.cleanupWarnings = cleanupWarnings;
    throw error;
  }

  async function saveOnce(result, signal, onRecord, byteSource = false) {
    let reader = null, timer = null, onExternalAbort = null, complete = false;
    const parser = streamOptions ? createResponseStreamParser(streamOptions) : null;
    const hash = createHash('sha256');
    let digest = null;
    const stop = () => { throw controller.signal.reason; };
    const check = () => { if (controller.signal.aborted) stop(); };
    const emitRecords = async records => {
      if (!onRecord) return;
      for (const record of records) {
        check();
        try {
          // Honor the same deadline even if a consumer never resolves.
          await readChunk({ read: () => Promise.resolve().then(() => onRecord(record)) }, controller.signal);
        } catch (cause) {
          check();
          throw new BuyerResponseFileError('RESPONSE_STREAM_CONSUMER_FAILED', '', { cause });
        }
      }
    };
    try {
      if (signal !== undefined && !(signal instanceof AbortSignal))
        throw new BuyerResponseFileError('BAD_RESPONSE_FILE_SIGNAL');
      if (onRecord !== undefined && (typeof onRecord !== 'function' || !parser))
        throw new BuyerResponseFileError('BAD_RESPONSE_STREAM_CONSUMER');
      if (signal) {
        onExternalAbort = () => controller.abort(new BuyerResponseFileError('RESPONSE_FILE_ABORTED'));
        signal.addEventListener('abort', onExternalAbort, { once: true });
        if (signal.aborted) onExternalAbort();
      }
      timer = setTimeout(() => controller.abort(new BuyerResponseFileError('RESPONSE_FILE_TIMEOUT')), timeoutMs);
      check();
      let body, contentType, objectMetadata = {};
      if (byteSource) {
        if (!(result.bytes instanceof Uint8Array) || result.bytes.byteLength > maxBytes)
          throw new BuyerResponseFileError('RESPONSE_FILE_BYTE_SOURCE_INVALID');
        if (typeof result.contentType !== 'string' || result.contentType.length > 256 ||
            /[\x00-\x1f\x7f]/.test(result.contentType))
          throw new BuyerResponseFileError('RESPONSE_FILE_BYTE_TYPE_INVALID');
        // Blob snapshots the caller's bytes. This is local serialization, with
        // no fabricated HTTP status, network response or payment outcome.
        body = new Blob([result.bytes]).stream();
        contentType = result.contentType;
      } else {
        const response = result?.response;
        if (!(response instanceof Response) || !response.ok)
          throw new BuyerResponseFileError('RESPONSE_FILE_HTTP_STATUS', 'a returned 2xx Response is required');
        if (response.bodyUsed || response.body?.locked)
          throw new BuyerResponseFileError('RESPONSE_FILE_BODY_UNAVAILABLE', 'save the unread original response');
        body = response.body; contentType = response.headers.get('content-type');
        objectMetadata = {
          contentRange: response.headers.get('content-range'),
          contentSha256: response.headers.get('x-content-sha256'),
          snapshot: response.headers.get('x-sf30-object-snapshot'),
          totalBytes: response.headers.get('x-sf30-object-bytes'),
        };
      }
      // Count the bytes Fetch exposes, not Content-Length: compression can make
      // that header describe a different representation than this stream.
      if (body) reader = body.getReader();
      if (pins.expectedContentType !== undefined &&
          contentType?.split(';', 1)[0].trim().toLowerCase() !== pins.expectedContentType)
        throw new BuyerResponseFileError('RESPONSE_FILE_TYPE_MISMATCH');
      if (parser && !responseStreamContentType(streamOptions.format, contentType))
        throw new BuyerResponseFileError('RESPONSE_STREAM_TYPE_MISMATCH');
      while (reader) {
        check();
        let chunk;
        // One cancellation listener per pending read, removed after that read;
        // no growing chain of Promise.race callbacks on a shared timer promise.
        try { chunk = await readChunk(reader, controller.signal); }
        catch (cause) {
          if (cause instanceof BuyerResponseFileError) throw cause;
          throw new BuyerResponseFileError('RESPONSE_FILE_READ_FAILED', '', { cause });
        }
        const { done, value } = chunk;
        if (done) break;
        if (!(value instanceof Uint8Array)) throw new BuyerResponseFileError('RESPONSE_FILE_BAD_CHUNK');
        if (value.byteLength > maxBytes - bytes)
          throw new BuyerResponseFileError('RESPONSE_FILE_TOO_LARGE', `limit ${maxBytes} bytes`);
        let offset = 0;
        while (offset < value.byteLength) {
          check();
          const { bytesWritten } = await file.write(value, offset, value.byteLength - offset, null);
          if (bytesWritten < 1) throw new BuyerResponseFileError('RESPONSE_FILE_WRITE_FAILED', 'write made no progress');
          hash.update(value.subarray(offset, offset + bytesWritten));
          bytes += bytesWritten;
          offset += bytesWritten;
        }
        if (parser) await emitRecords(parser.push(value));
      }
      if (parser) {
        await emitRecords(parser.finish());
        if (!parser.summary().complete)
          throw new BuyerResponseFileError('RESPONSE_STREAM_INCOMPLETE_RECORD');
      }
      check();
      await file.sync();
      await file.close();
      file = null;
      check();
      digest = hash.digest('hex');
      const saved = { path: finalPath, bytes, sha256: digest, contentType,
        ...(parser ? { stream: parser.summary() } : {}) };
      // A completed transfer is not yet an accepted product. Leave a mismatched
      // private partial for reconciliation; never publish it under the buyer's name.
      if (pins.expectedBytes !== undefined && bytes !== pins.expectedBytes)
        throw new BuyerResponseFileError('RESPONSE_FILE_SIZE_MISMATCH');
      if (pins.expectedSha256 !== undefined && saved.sha256 !== pins.expectedSha256)
        throw new BuyerResponseFileError('RESPONSE_FILE_DIGEST_MISMATCH');
      if (Object.keys(pins).length) saved.verifiedAgainst = { ...pins };
      if (Object.values(objectMetadata).some(value => value !== null))
        saved.objectMetadata = objectMetadata;
      // link is atomic and fails when the destination exists; rename would
      // silently overwrite a file created after the original preflight.
      try { await link(partialPath, finalPath); }
      catch (cause) {
        throw new BuyerResponseFileError(cause.code === 'EEXIST' ? 'RESPONSE_FILE_EXISTS' : 'RESPONSE_FILE_PUBLISH_FAILED', finalPath, { cause });
      }
      complete = true;
      state = 'SAVED';
      clearTimeout(timer);
      const cleanupWarnings = await cleanup();
      return { ...saved, cleanupWarnings };
    } catch (cause) {
      state = 'FAILED';
      if (reader) { try { void reader.cancel().catch(() => {}); } catch {} }
      const cleanupWarnings = await cleanup({ keepPartial: bytes > 0 });
      const error = cause instanceof BuyerResponseFileError ? cause : new BuyerResponseFileError(
        cause instanceof BuyerResponseStreamError ? cause.code : 'RESPONSE_FILE_WRITE_FAILED', '', { cause });
      error.bytes = bytes;
      error.partialPath = bytes > 0 ? partialPath : null;
      error.cleanupWarnings = cleanupWarnings;
      if (parser) {
        error.stream = { ...parser.summary(), complete: false };
        error.partialSha256 = digest ?? hash.digest('hex');
      }
      throw error;
    } finally {
      clearTimeout(timer);
      if (onExternalAbort) signal.removeEventListener('abort', onExternalAbort);
      if (reader) {
        // A remote source's unresolved cancellation must not hold the caller.
        if (!complete) { try { void reader.cancel().catch(() => {}); } catch {} }
        try { reader.releaseLock(); } catch {}
      }
    }
  }

  return Object.freeze({
    destination: finalPath,
    partialPath,
    save(result, { signal, onRecord } = {}) {
      if (state !== 'PREPARED')
        return Promise.reject(new BuyerResponseFileError('RESPONSE_FILE_NOT_PREPARED', state));
      state = 'SAVING';
      activeSave = saveOnce(result, signal, onRecord);
      return activeSave;
    },
    /** Save already-returned non-HTTP bytes through the same reserved writer. */
    saveBytes(bytes, { contentType = 'application/octet-stream', signal } = {}) {
      if (state !== 'PREPARED')
        return Promise.reject(new BuyerResponseFileError('RESPONSE_FILE_NOT_PREPARED', state));
      state = 'SAVING';
      activeSave = saveOnce({ bytes, contentType }, signal, undefined, true);
      return activeSave;
    },
    async abort() {
      if (state === 'SAVING') {
        controller.abort(new BuyerResponseFileError('RESPONSE_FILE_ABORTED'));
        try { await activeSave; } catch {}
      } else if (state === 'PREPARED') {
        state = 'ABORTED';
        const cleanupWarnings = await cleanup();
        if (cleanupWarnings.length)
          throw new BuyerResponseFileError('RESPONSE_FILE_CLEANUP_FAILED', '', { cleanupWarnings });
      }
    },
  });
}

// MIT — Incremental framing for one original HTTP response. No requests or retries.
const LIMIT = 64 * 1024 * 1024;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);

export class BuyerResponseStreamError extends Error {
  constructor(code) { super(code); this.name = 'BuyerResponseStreamError'; this.code = code; }
}
const need = (condition, code) => { if (!condition) throw new BuyerResponseStreamError(code); };

/** Pure configuration validation, suitable before the original paid request. */
export function normalizeResponseStream(value) {
  need(object(value) && Object.keys(value).every(key =>
    ['format', 'maxRecordBytes', 'maxRecords'].includes(key)), 'BAD_RESPONSE_STREAM_OPTIONS');
  const { format, maxRecordBytes = 1048576, maxRecords = 100000 } = value;
  need(['sse', 'ndjson'].includes(format), 'BAD_RESPONSE_STREAM_FORMAT');
  need(Number.isSafeInteger(maxRecordBytes) && maxRecordBytes > 0 && maxRecordBytes <= LIMIT,
    'BAD_RESPONSE_STREAM_RECORD_LIMIT');
  need(Number.isSafeInteger(maxRecords) && maxRecords > 0 && maxRecords <= 1000000,
    'BAD_RESPONSE_STREAM_COUNT_LIMIT');
  return Object.freeze({ format, maxRecordBytes, maxRecords });
}

export function responseStreamContentType(format, value) {
  if (typeof value !== 'string') return false;
  const [type, ...parameters] = value.toLowerCase().split(';').map(part => part.trim());
  const charsets = parameters.filter(part => /^charset\s*=/.test(part));
  if (charsets.length > 1 || charsets.some(part =>
    !/^charset\s*=\s*(?:utf-8|utf8|"utf-8"|"utf8")$/.test(part))) return false;
  return format === 'sse' ? type === 'text/event-stream' : format === 'ndjson' &&
    ['application/x-ndjson', 'application/ndjson'].includes(type);
}

/**
 * Byte-preserving framing. Every returned record belongs to bytes already
 * supplied to push(). SSE follows the standard CR/LF, comment, data, event, id
 * and retry rules; EOF never dispatches an unfinished event. NDJSON requires
 * a newline after each JSON value and ignores empty/whitespace-only lines.
 * UTF-8 is fatal; limits apply to the complete wire record, including framing.
 */
export function createResponseStreamParser(options) {
  const config = normalizeResponseStream(options);
  const { format, maxRecordBytes, maxRecords } = config;
  const decoder = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });
  let lineBuffer = Buffer.allocUnsafe(Math.min(4096, maxRecordBytes));
  let lineBytes = 0, recordBytes = 0, lastRecordBytes = 0, totalBytes = 0;
  let records = 0, emptyLines = 0, complete = false, ended = false, failed = null;
  let firstLine = true, skipLF = false, lastCompleteByte = 0;
  let data = [], dataPresent = false, event = '', lastEventId = '', retryMilliseconds = null;
  const pending = () => lineBytes > 0 || (format === 'sse' && dataPresent);
  const summary = () => Object.freeze({ format, records, bytes: totalBytes,
    complete, pendingRecord: pending(), lastCompleteByte,
    ...(format === 'sse' ? { lastEventId, retryMilliseconds } : { emptyLines }),
    ...(failed ? { error: failed } : {}) });
  function error(code) {
    failed = code;
    const result = new BuyerResponseStreamError(code);
    result.stream = summary();
    throw result;
  }
  function append(piece) {
    if (piece.length === 0) return;
    if (piece.length > maxRecordBytes - recordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
    const size = lineBytes + piece.length;
    if (size > lineBuffer.length) {
      const next = Buffer.allocUnsafe(Math.min(maxRecordBytes, Math.max(size, lineBuffer.length * 2)));
      lineBuffer.copy(next, 0, 0, lineBytes); lineBuffer = next;
    }
    lineBuffer.set(piece, lineBytes); lineBytes = size; recordBytes += piece.length;
  }
  function record(value, output) {
    if (records >= maxRecords) error('RESPONSE_STREAM_TOO_MANY_RECORDS');
    records++;
    output.push(Object.freeze({ index: records - 1, ...value }));
  }
  function line(output) {
    let text;
    try { text = decoder.decode(lineBuffer.subarray(0, lineBytes)); }
    catch { error('RESPONSE_STREAM_UTF8_INVALID'); }
    lineBytes = 0;
    if (firstLine) { firstLine = false; if (text.startsWith('\ufeff')) text = text.slice(1); }
    if (format === 'ndjson') {
      if (text.endsWith('\r')) text = text.slice(0, -1);
      if (text.includes('\r')) error('RESPONSE_STREAM_JSON_INVALID');
      if (text.trim().length === 0) emptyLines++;
      else {
        let value;
        try { value = JSON.parse(text); } catch { error('RESPONSE_STREAM_JSON_INVALID'); }
        record({ format, value }, output);
      }
      recordBytes = 0; lastCompleteByte = totalBytes;
      return;
    }
    if (text === '') {
      if (dataPresent) record({ format, event: event || 'message', data: data.join('\n'),
        id: lastEventId, ...(retryMilliseconds === null ? {} : { retry: retryMilliseconds }) }, output);
      else emptyLines++;
      data = []; dataPresent = false; event = ''; lastRecordBytes = recordBytes;
      recordBytes = 0; lastCompleteByte = totalBytes;
      return;
    }
    if (text.startsWith(':')) return;
    const colon = text.indexOf(':');
    const field = colon === -1 ? text : text.slice(0, colon);
    let value = colon === -1 ? '' : text.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') { data.push(value); dataPresent = true; }
    else if (field === 'event') event = value;
    else if (field === 'id' && !value.includes('\0')) lastEventId = value;
    else if (field === 'retry' && /^[0-9]+$/.test(value) && Number.isSafeInteger(Number(value)))
      retryMilliseconds = Number(value);
  }
  function push(value) {
    need(!ended && failed === null, 'RESPONSE_STREAM_PARSER_CLOSED');
    need(value instanceof Uint8Array, 'RESPONSE_STREAM_BAD_CHUNK');
    const bytes = Buffer.from(value.buffer, value.byteOffset, value.byteLength), output = [];
    let start = 0;
    for (let i = 0; i < bytes.length; i++) {
      const byte = bytes[i];
      if (skipLF) {
        skipLF = false;
        if (byte === 10) { totalBytes++; start = i + 1;
          if (recordBytes === 0) {
            if (++lastRecordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
            lastCompleteByte = totalBytes;
          }
          else { if (++recordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE'); }
          continue;
        }
      }
      if (byte !== 10 && (format !== 'sse' || byte !== 13)) continue;
      append(bytes.subarray(start, i));
      totalBytes += i - start + 1;
      if (++recordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
      line(output);
      skipLF = format === 'sse' && byte === 13;
      start = i + 1;
    }
    append(bytes.subarray(start)); totalBytes += bytes.length - start;
    return output;
  }
  function finish() {
    need(!ended && failed === null, 'RESPONSE_STREAM_PARSER_CLOSED');
    ended = true;
    // Validate even the undispatched tail. Do not emit it as a completed record.
    if (lineBytes) {
      try { decoder.decode(lineBuffer.subarray(0, lineBytes)); }
      catch { error('RESPONSE_STREAM_UTF8_INVALID'); }
    }
    complete = !pending();
    return [];
  }
  return Object.freeze({ push, finish, summary, options: config });
}

/** Decode retained bytes or one live body with normal async-iterator backpressure. */
export async function* parseResponseStream(chunks, { signal, ...options }) {
  need(signal === undefined || signal instanceof AbortSignal, 'BAD_RESPONSE_STREAM_SIGNAL');
  const parser = createResponseStreamParser(options);
  for await (const chunk of chunks) {
    need(!signal?.aborted, 'RESPONSE_STREAM_ABORTED');
    yield* parser.push(chunk);
  }
  need(!signal?.aborted, 'RESPONSE_STREAM_ABORTED');
  yield* parser.finish();
  if (!parser.summary().complete) {
    const error = new BuyerResponseStreamError('RESPONSE_STREAM_INCOMPLETE_RECORD');
    error.stream = parser.summary();
    throw error;
  }
}

/** Safe, side-effect-free error interpretation for Stellar Forge's x402 v2 adapters.
 * Does not sign, broadcast, retry a paid request, or query a ledger.
 */
export const VERSION = 'stellar-forge.failure.v1';
export const STAGES = Object.freeze(['verify', 'settle', 'discovery', 'mcp', 'wallet']);
export const ACTIONS = Object.freeze({
  STOP: 'stop', REQUOTE_AND_REAUTHORIZE: 'requote_and_reauthorize',
  REAUTHORIZE: 'reauthorize', CHECK_ACCOUNT: 'check_account',
  CHANGE_ROUTE: 'change_route', RETRY_READ: 'retry_read',
  RECONCILE_SETTLEMENT: 'reconcile_settlement', REQUEST_APPROVAL: 'request_approval',
});

// Canonical x402 v2 codes plus local orchestration errors. Map prevents inherited
// property names (e.g. constructor, __proto__) being mistaken for known errors.
const ENTRIES = new Map([
  ['insufficient_funds', ['check_account', 'Wallet balance insufficient']],
  ['invalid_exact_evm_payload_authorization_valid_after', ['reauthorize', 'Authorization is not yet valid']],
  ['invalid_exact_evm_payload_authorization_valid_before', ['reauthorize', 'Authorization expired']],
  ['invalid_exact_evm_payload_authorization_value_mismatch', ['requote_and_reauthorize', 'Payment amount differs from terms']],
  ['invalid_exact_evm_payload_signature', ['reauthorize', 'Authorization signature invalid']],
  ['invalid_exact_evm_payload_recipient_mismatch', ['requote_and_reauthorize', 'Payment recipient differs from terms']],
  ['invalid_network', ['change_route', 'Unsupported network']],
  ['invalid_payload', ['stop', 'Invalid payment payload']],
  ['invalid_payment_requirements', ['stop', 'Invalid payment requirements']],
  ['invalid_scheme', ['change_route', 'Invalid payment scheme']],
  ['unsupported_scheme', ['change_route', 'Unsupported payment scheme']],
  ['invalid_x402_version', ['stop', 'Unsupported protocol version']],
  ['invalid_transaction_state', ['stop', 'Ledger transaction failed']],
  ['unexpected_verify_error', ['stop', 'Unexpected verification error']],
  ['unexpected_settle_error', ['reconcile_settlement', 'Settlement result uncertain']],
  ['settlement_pending', ['reconcile_settlement', 'Settlement confirmation pending']],
  ['discovery_not_found', ['stop', 'Resource is not indexed']],
  ['discovery_stale_terms', ['requote_and_reauthorize', 'Resource terms changed']],
  ['seller_identity_unverified', ['request_approval', 'Seller identity not verified']],
  ['wallet_trustline_missing', ['check_account', 'Wallet trustline missing']],
  ['budget_exceeded', ['request_approval', 'Buyer policy budget exceeded']],
  ['rpc_unavailable', ['retry_read', 'Read-only RPC unavailable']],
  ['rate_limited', ['retry_read', 'Read-only request rate limited']],
  ['timeout', ['retry_read', 'Read-only request timed out']],
  ['mcp_tool_missing', ['stop', 'MCP tool not found']],
]);
const TOKEN = /^[a-zA-Z0-9_.:-]{1,128}$/;
const clean = v => typeof v === 'string' && TOKEN.test(v) ? v : null;
const uncertainCodes = new Set(['settlement_pending', 'unexpected_settle_error', 'timeout', 'rpc_unavailable']);

/** Takes canonical verify/settle response shapes without modifying them. */
export function explainFailure({stage, reason, response = null, traceId, retryAfterMs} = {}) {
  if (!STAGES.includes(stage)) throw new TypeError('Invalid failure stage');
  if (response !== null && (typeof response !== 'object' || Array.isArray(response))) {
    throw new TypeError('response must be an object');
  }
  if (stage === 'verify' && response?.isValid === true) throw new TypeError('verify result is successful');
  if (stage === 'settle' && response?.success === true) throw new TypeError('settlement result is successful');
  const raw = stage === 'verify' ? response?.invalidReason ?? reason :
    stage === 'settle' ? response?.errorReason ?? reason : reason;
  const code = clean(raw) ?? 'unknown_upstream_error';
  const [action, text] = ENTRIES.get(code) ?? ['stop', 'Unrecognized upstream error'];
  const transaction = clean(response?.transaction);
  const network = clean(response?.network);
  const malformedPending = code === 'settlement_pending' && (!transaction || !network);
  const mayHaveSubmitted = stage === 'settle';
  const reconcile = mayHaveSubmitted && uncertainCodes.has(code);
  const recoveryAction = reconcile ? ACTIONS.RECONCILE_SETTLEMENT : action;
  const safeToAutoRetry = (stage === 'verify' || stage === 'discovery') && recoveryAction === ACTIONS.RETRY_READ;
  const result = {
    version: VERSION,
    code: malformedPending ? 'invalid_settlement_pending_response' : code,
    reason: malformedPending ? 'Pending settlement lacks transaction or network' : text,
    stage, traceId: clean(traceId) ?? 'unspecified', recoveryAction, safeToAutoRetry,
    requiresNewPaymentAuthorization: recoveryAction === ACTIONS.REAUTHORIZE ||
      recoveryAction === ACTIONS.REQUOTE_AND_REAUTHORIZE,
    settlementMayBePending: reconcile,
    settlement: mayHaveSubmitted ? Object.freeze({transaction, network, confirmed: false}) : null,
  };
  if (safeToAutoRetry && Number.isSafeInteger(retryAfterMs) && retryAfterMs >= 0 && retryAfterMs <= 3600000) {
    result.retryAfterMs = retryAfterMs;
  }
  return Object.freeze(result);
}

/** Trust only an independently obtained canonical ledger receipt, never model text.
 * All results have maySubmitPayment=false: a separate operator must authorize any payment.
 */
// Do not infer a payment transfer from transaction inclusion alone.
const PAYMENT_ATOMIC = /^[1-9][0-9]{0,77}$/;
function matchingVerifiedTransfer(receipt, expectedPayment) {
  if (receipt?.transferVerified !== true || !Array.isArray(receipt.transfers) ||
      receipt.transfers.length !== 1 || !expectedPayment) return false;
  const transfer = receipt.transfers[0];
  if (!transfer || typeof transfer !== 'object' || Array.isArray(transfer)) return false;
  if (!['from','payTo','asset'].every(k => clean(expectedPayment[k]) !== null) ||
      typeof expectedPayment.amount !== 'string' ||
      !PAYMENT_ATOMIC.test(expectedPayment.amount)) return false;
  return transfer.from === expectedPayment.from &&
    transfer.to === expectedPayment.payTo && transfer.asset === expectedPayment.asset &&
    transfer.amount === expectedPayment.amount;
}

export function gateNextAction(failure, {ledgerReceipt, expectedPayment, explicitNewAuthorization = false} = {}) {
  if (!failure || failure.version !== VERSION) throw new TypeError('unrecognized failure envelope');
  if (failure.settlementMayBePending) {
    const transaction = failure.settlement?.transaction;
    const network = failure.settlement?.network;
    const settled = Boolean(transaction && network && ledgerReceipt?.confirmed === true &&
      ledgerReceipt?.success === true && ledgerReceipt.transaction === transaction && ledgerReceipt.network === network &&
      matchingVerifiedTransfer(ledgerReceipt, expectedPayment));
    return Object.freeze({decision: settled ? 'already_settled' : 'reconcile_before_any_new_payment',
      maySubmitPayment: false, requiresManualReview: !settled});
  }
  if (failure.requiresNewPaymentAuthorization) {
    return Object.freeze({decision: explicitNewAuthorization ? 'prepare_new_authorization' : 'await_user_authorization',
      maySubmitPayment: false, requiresManualReview: !explicitNewAuthorization});
  }
  if (failure.safeToAutoRetry) {
    return Object.freeze({decision: 'retry_read_only_operation', maySubmitPayment: false, requiresManualReview: false});
  }
  return Object.freeze({decision: 'stop_or_request_user_action', maySubmitPayment: false, requiresManualReview: true});
}

#!/usr/bin/env node
/** Forward the installed buyer-expenses command to its original Python server. */
import {spawn} from "node:child_process";
import {constants} from "node:os";
import {resolve} from "node:path";
import {fileURLToPath} from "node:url";

export function main(args = process.argv.slice(2)) {
  return new Promise((resolveRun, reject) => {
    const child = spawn("python3", [fileURLToPath(new URL("./server.py", import.meta.url)), "--node", process.execPath, ...args],
      {stdio: "inherit", shell: false, windowsHide: true});
    const interrupt = () => child.kill("SIGINT");
    const terminate = () => child.kill("SIGTERM");
    const detach = () => {
      process.off("SIGINT", interrupt);
      process.off("SIGTERM", terminate);
    };
    process.on("SIGINT", interrupt);
    process.on("SIGTERM", terminate);
    child.once("error", error => {detach(); reject(error);});
    child.once("exit", (code, signal) => {
      detach();
      const status = code ?? 128 + (constants.signals[signal] ?? 1);
      resolveRun(status);
    });
  });
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().then(code => {process.exitCode = code;}).catch(error => {
    console.error("Buyer expense workspace: " + error.message);
    process.exitCode = 1;
  });
}

"""Expense coding and period views over original native statement rows."""
from __future__ import annotations

import hashlib
import json
import re
from datetime import datetime, timezone
from uuid import uuid4
from native import COLUMNS, utc_day

SCHEMA = "stellar-forge.buyer-expense-workspace.v1"
INTEGER = re.compile(r"(?:0|[1-9][0-9]{0,99})")


class Problem(ValueError):
    def __init__(self, code, message, status=400):
        super().__init__(message)
        self.code, self.status = code, status


def now():
    return datetime.now(timezone.utc).isoformat()


def canonical(value):
    return json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def identifier(prefix):
    return prefix + "-" + str(uuid4())


def text(value, label, *, maximum=1000, optional=False):
    if not isinstance(value, str):
        raise Problem("INVALID_TEXT", label + " must be text")
    value = value.strip()
    if (not value and not optional) or len(value) > maximum or any(ord(c) < 32 and c not in "\n\t" for c in value):
        raise Problem("INVALID_TEXT", label + " is empty, too long, or contains control characters")
    return value


def day(value):
    try:
        return utc_day(value)
    except (ValueError, TypeError) as exc:
        raise Problem("INVALID_DATE", "Use a complete calendar date in YYYY-MM-DD form") from exc


def amount(value):
    if not isinstance(value, str) or INTEGER.fullmatch(value) is None:
        raise Problem("INVALID_AMOUNT", "Enter an exact nonnegative base-unit integer as text")
    return int(value)


def row_key(source_id, request_id):
    return digest([source_id, request_id])


def basis(row, missing=False):
    value = {"row": {key: row[key] for key in COLUMNS}, "missing": bool(missing)}
    if row.get("native_context_sha256"):
        value["native_context_sha256"] = row["native_context_sha256"]
    return digest(value)


def native_changes(previous, current):
    before = {r["request_id"]: r for r in (previous or {}).get("rows", [])}
    after = {r["request_id"]: r for r in current["rows"]}
    changes = []
    for request_id in sorted(before.keys() | after.keys()):
        a, b = before.get(request_id), after.get(request_id)
        if a is None:
            changes.append({"request_id": request_id, "kind": "ADDED", "before": None, "after": b})
        elif b is None:
            changes.append({"request_id": request_id, "kind": "ABSENT", "before": a, "after": None})
        elif any(a.get(k) != b.get(k) for k in (*COLUMNS, "native_context_sha256")):
            changes.append({"request_id": request_id, "kind": "CHANGED", "before": a, "after": b,
                            "fields": [k for k in (*COLUMNS, "native_context_sha256") if a.get(k) != b.get(k)]})
    return changes


def validate_coding(item, payload, centers):
    row = item["row"]
    if item["missing"] or row["state"] != "settled":
        raise Problem("NATIVE_SETTLEMENT_REQUIRED", "Code a present, settled native row; review other rows as period exceptions")
    if payload.get("basis") != item["basis"]:
        raise Problem("ROW_CHANGED", "The native row changed. Review its current values before saving", 409)
    recognition = day(payload.get("recognition_date"))
    allocations = payload.get("allocations")
    if not isinstance(allocations, list) or not 1 <= len(allocations) <= 100:
        raise Problem("INVALID_ALLOCATIONS", "Add one to 100 allocation lines")
    normalized = []
    total = 0
    for line in allocations:
        if not isinstance(line, dict):
            raise Problem("INVALID_ALLOCATIONS", "Each allocation must be an object")
        center = centers.get(line.get("center_id"))
        if center is None or not center["active"]:
            raise Problem("COST_CENTER_REQUIRED", "Choose an active cost center for each line")
        value = amount(line.get("amount"))
        total += value
        normalized.append({"center_id": center["id"], "amount": str(value),
                           "project": text(line.get("project", ""), "Project", maximum=160, optional=True),
                           "account_code": text(line.get("account_code", ""), "Account code", maximum=120, optional=True),
                           "memo": text(line.get("memo", ""), "Line memo", maximum=1000, optional=True)})
    if total != int(row["settled_base_units"]):
        raise Problem("ALLOCATION_TOTAL", "Allocation lines must equal the native settled actual of " + row["settled_base_units"] + " base units")
    return {"item_id": item["id"], "basis": item["basis"], "recognition_date": recognition,
            "memo": text(payload.get("memo", ""), "Expense memo", maximum=4000, optional=True),
            "operator": text(payload.get("operator"), "Coding owner", maximum=240), "allocations": normalized}


def group_amounts(lines, dimensions=()):
    groups = {}
    for line in lines:
        key = tuple(line[k] for k in ("network", "asset", *dimensions))
        entry = groups.setdefault(key, {k: line[k] for k in ("network", "asset", *dimensions)} | {"amount": 0, "lines": 0})
        entry["amount"] += int(line["amount"])
        entry["lines"] += 1
    return [value | {"amount": str(value["amount"])} for _, value in sorted(groups.items())]


def period_view(period, items, sources, centers, dispositions, closed_transfers=None):
    """Dates are operator recognition dates; native days never become settlement dates."""
    start, through = period["from_day"], period["through_day"]
    source_views = [{k: s.get(k) for k in ("id", "name", "kind", "path", "current_capture", "capture_time", "projection_sha256", "journal_events", "last_sequence", "record_kind", "source_basis", "date_basis")}
                    for s in sources]
    issues, candidates, exposures, native_outcomes = [], [], [], []
    disposition_by_key = {(d["item_id"], d["code"]): d for d in dispositions}
    closed_transfers = sorted(closed_transfers or [], key=lambda v:(v["period_id"], v["close_id"], v["item_id"]))
    previously_issued = {}
    for entry in closed_transfers:
        previously_issued.setdefault(entry["transfer_identity"], []).append(entry)

    def issue(code, item, description, *, group=None, kinds=None):
        item_id = item["id"] if item else ""
        selected = disposition_by_key.get((item_id, code))
        issue_basis = digest({"code": code, "basis": item["basis"] if item else None, "group": group})
        allowed = ["carry_forward", "exclude_from_period"] if kinds is None else kinds
        valid = bool(selected and selected["basis"] == issue_basis and selected["kind"] in allowed)
        result = {"code": code, "item_id": item_id, "request_id": item["row"]["request_id"] if item else None,
                  "source_name": item.get("source_name") if item else None, "description": description,
                  "source_capture": item.get("capture_id") if item else None,
                  "basis": issue_basis, "allowed_kinds": allowed, "resolved": valid,
                  "disposition": selected if valid else None, "group": group}
        issues.append(result)
        return result

    for source in sources:
        if source.get("pending"):
            issue("SOURCE_REVIEW_" + source["id"], None, source["name"] + " has captured source awaiting acceptance or rejection",
                  group={"source_id": source["id"], "captures": source["pending"]}, kinds=[])
        elif not source.get("current_capture"):
            issue("SOURCE_CAPTURE_" + source["id"], None, source["name"] + " has no accepted native capture",
                  group={"source_id": source["id"]}, kinds=[])

    def receipt_key(row):
        ref = row.get("receipt_ref", "")
        matched = re.fullmatch(re.escape(row["network"]) + r"/([0-9a-fA-F]{64})", ref)
        if matched:
            ref = row["network"] + "/" + matched.group(1).lower()
        elif re.fullmatch(r"[0-9a-fA-F]{64}", ref):
            ref = row["network"] + "/" + ref.lower()
        return (row["network"], row["asset"], ref)

    receipt_groups, exact_transfers = {}, {}
    for item in items:
        row = item["row"]
        if row["state"] == "settled" and row.get("receipt_ref") and not item["missing"]:
            key = receipt_key(row)
            receipt_groups.setdefault(key, []).append(item)
            transfer = row.get("native_detail", {}).get("transfer_identity")
            if transfer:
                exact_transfers.setdefault(transfer, []).append(item)

    for item in items:
        row, coding = item["row"], item.get("coding")
        relevant = row["day"] <= through or bool(coding and start <= coding["recognition_date"] <= through)
        if not relevant:
            continue
        detail = row.get("native_detail")
        if isinstance(detail, dict):
            native_outcomes.append({"item_id":item["id"], "request_id":row["request_id"], "source_name":item["source_name"],
                "source_capture":item["capture_id"], "quote_day":row["day"], "native_status":detail["native_status"],
                "payment_classification":detail["classification"], "network":row["network"], "asset":row["asset"],
                "quoted_amount":detail.get("quoted_amount"), "settled_actual":row["settled_base_units"],
                "receipt_ref":row["receipt_ref"], "observation_sha256":detail.get("observation_sha256"),
                "transfer_identity":detail.get("transfer_identity"), "payer":detail.get("payer"),
                "recipient":detail.get("recipient"), "result_file":detail.get("result_file"),
                "result_preview":detail.get("result_preview"),
                "result_file_status":(detail.get("result_file") or {}).get("status"),
                "result_file_sha256":(detail.get("result_file") or {}).get("sha256"),
                "result_file_bytes":(detail.get("result_file") or {}).get("bytes"),
                "result_preview_sha256":(detail.get("result_preview") or {}).get("bodySha256"),
                "result_preview_bytes":(detail.get("result_preview") or {}).get("bodyBytes"),
                "missing":item["missing"]})
        if row["state"] == "reserved":
            exposures.append({"item_id": item["id"], "request_id": row["request_id"], "source_name": item["source_name"],
                              "network": row["network"], "asset": row["asset"], "amount": row["reserved_base_units"],
                              "native_reservation_day": row["day"], "missing": item["missing"],
                              "source_capture": item["capture_id"], "request_digest": row["request_digest"]})
        if item["missing"]:
            issue("ABSENT_FROM_CURRENT_SOURCE", item, "This original row is absent from the accepted source capture; its previous bytes remain retained")
            continue
        if row["state"] == "reserved":
            issue("UNRESOLVED_RESERVATION", item, "The original maximum remains reserved. Carry it for native finalization; it is not settled expense")
            continue
        if row["state"] == "not_dispatched":
            continue
        if row["state"] == "failed":
            issue("FAILED_NATIVE_PAYMENT", item, "The original saved RPC observation reports this transaction failed. Record its period disposition; the quote amount is not an expense.")
            continue
        if row["state"] == "unresolved":
            issue("NATIVE_PAYMENT_UNRESOLVED", item, "The original buyer retains a signed dispatch without a matched transfer observation. Carry or exclude this quote while its original payment recovery continues; its quoted amount is not a spending reservation.")
            continue
        if row["state"] == "observation_review":
            issue("NATIVE_OBSERVATION_BINDING", item, "The saved original payment observation does not match this quote's retained native binding. Inspect the original buyer observation and refresh its source.", group={"source_id":item["source_id"]}, kinds=[])
            continue
        if coding and coding["recognition_date"] < start:
            if coding["basis"] != item["basis"]:
                issue("EARLIER_PERIOD_SOURCE_CHANGED", item, "The native row changed after earlier-date coding; review that original period")
            continue
        if coding and coding["recognition_date"] > through:
            if coding["basis"] != item["basis"]:
                issue("FUTURE_CODING_SOURCE_CHANGED", item, "The native row changed after future-date coding; update the allocation")
            continue
        if coding is None:
            issue("UNCODED_SETTLED_ROW", item, "Assign an accounting date and exact cost-center allocation, or record its disposition")
            continue
        if coding["basis"] != item["basis"]:
            issue("CODING_SOURCE_CHANGED", item, "The native row differs from the allocation's reviewed source; update coding or record its disposition")
            continue
        transfer_identity = row.get("native_detail", {}).get("transfer_identity")
        prior = previously_issued.get(transfer_identity, [])
        if prior:
            issue("TRANSFER_ALREADY_ISSUED", item,
                  "The same original transfer is included in another currently closed period. Exclude this representation, or reopen and correct the earlier period before recognising it here.",
                  group={"issued_charges":prior}, kinds=["exclude_from_period"])
            continue
        selected_lines = []
        for index, line in enumerate(coding["allocations"]):
            center = centers.get(line["center_id"])
            if center is None:
                raise Problem("COST_CENTER_MISSING", "A retained allocation references a missing cost center", 409)
            selected_lines.append({"item_id": item["id"], "source_id": item["source_id"], "source_name": item["source_name"],
                                   "request_id": row["request_id"], "request_digest": row["request_digest"],
                                   "native_reservation_day": row["day"] if row.get("source_kind") != "mcp_quote" else None,
                                   "native_source_day":row["day"], "native_date_basis":row.get("native_date_basis", "SF36 reservation day"),
                                   "source_kind":row.get("source_kind", "sf36_ledger"), "recognition_date": coding["recognition_date"],
                                   "network": row["network"], "asset": row["asset"], "scheme": row["scheme"],
                                   "settled_actual": row["settled_base_units"],
                                   "reserved_maximum":row["amount"] if row.get("source_kind") != "mcp_quote" else None,
                                   "quoted_amount":row["amount"] if row.get("source_kind") == "mcp_quote" else None,
                                   "receipt_ref": row["receipt_ref"], "proof_sha256": row["proof_sha256"],
                                   "center_id": center["id"], "center_code": center["code"], "center_name": center["name"],
                                   "project": line["project"], "account_code": line["account_code"], "amount": line["amount"],
                                   "memo": line["memo"] or coding["memo"], "coding_id": coding["id"], "line": index + 1,
                                   "source_capture": item["capture_id"], "basis": item["basis"],
                                   "native_payment": row.get("native_detail")})
        group = receipt_groups.get(receipt_key(row), [])
        exact = exact_transfers.get(row.get("native_detail", {}).get("transfer_identity"), [])
        exclude = False
        if len(group) > 1:
            same_transfer = len(exact) > 1
            shared = issue("SHARED_RECEIPT_REFERENCE", item,
                           "These original rows record the same native transfer event. Include one original charge and exclude duplicates." if same_transfer else
                           "More than one registered native row uses this transaction reference; review whether these are distinct charges or a duplicate source.",
                           group={"items": sorted([{"id": x["id"], "basis": x["basis"]} for x in group], key=lambda x: x["id"]),
                                  "same_transfer_items":sorted(x["id"] for x in exact) if same_transfer else []},
                           kinds=["include_original_charge", "exclude_from_period"] if same_transfer else ["separate_native_rows", "exclude_from_period"])
            exclude = bool(shared["resolved"] and shared["disposition"]["kind"] == "exclude_from_period")
        if not exclude:
            candidates.extend(selected_lines)

    # Two source rows with the same original native event cannot both become expense.
    included = {line["item_id"] for line in candidates}
    for values in exact_transfers.values():
        selected = included.intersection(item["id"] for item in values)
        if len(selected) > 1:
            for shared in issues:
                if shared["code"] == "SHARED_RECEIPT_REFERENCE" and shared["item_id"] in selected:
                    shared["resolved"] = False
                    shared["description"] = "The same original native transfer is still allocated more than once. Keep one included charge and exclude the duplicate source rows."
    unresolved = [x for x in issues if not x["resolved"]]
    context = {"period": {k: period[k] for k in ("id", "name", "from_day", "through_day", "generation")},
               "sources": source_views, "items": [{"id": i["id"], "basis": i["basis"], "coding": i.get("coding")} for i in items],
               "centers": sorted(centers.values(), key=lambda x: x["id"]), "dispositions": dispositions,
               "pending_sources": [{"id": s["id"], "pending": s.get("pending", [])} for s in sources],
               "closed_native_transfers":closed_transfers}
    return {"schema": "stellar-forge.buyer-expense-period.v1", "period": period, "source_captures": source_views,
            "context_sha256": digest(context), "ready": not unresolved, "issues": issues,
            "unresolved": len(unresolved), "allocations": candidates, "totals": group_amounts(candidates),
            "by_cost_center": group_amounts(candidates, ("center_code", "center_name")),
            "by_project": group_amounts(candidates, ("project",)), "outstanding_reservations": exposures,
            "outstanding_totals": group_amounts(exposures), "native_payment_outcomes":native_outcomes,
            "basis": "Original SF36 ledger projections and retained MCP quote/payment observations; source finalization remains with each original buyer",
            "date_basis": "Operator-assigned recognition dates; original reservation or quote-creation days retain their own source meaning",
            "unit_basis": "Exact native base-unit strings, grouped by network and asset; no fiat conversion"}

