  if (!plain(term) || term.scheme !== 'exact' || term.network !== 'stellar:testnet' ||
      typeof term.asset !== 'string' || !/^C[A-Z2-7]{55}$/.test(term.asset) ||
      typeof term.payTo !== 'string' || !/^G[A-Z2-7]{55}$/.test(term.payTo) ||
