      !Number.isSafeInteger(tx.ledger) || tx.ledger <= 0) {
    return failure(tx.status === 'NOT_FOUND' ? 'RPC_TRANSACTION_NOT_FOUND' : 'RPC_TRANSACTION_NOT_SUCCESS',
